#!/bin/bash

# .env ファイルを読み込む
if [ -f .env ]; then
    source .env
else
    echo "Error: .env file not found."
    exit 1
fi

# 環境変数のチェック
if [ -z "$FTP_HOST" ] || [ -z "$FTP_USER" ] || [ -z "$FTP_PASS" ] || [ -z "$REMOTE_DIR" ]; then
    echo "Error: FTP environment variables (FTP_HOST, FTP_USER, FTP_PASS, REMOTE_DIR) are not set in .env file."
    exit 1
fi

LOCAL_PROJECT_ROOT=$(pwd)

echo "Connecting to FTP host: $FTP_HOST"

# アップロード対象のファイルとディレクトリ
# venv は非常に大きいため、注意が必要です。
# lftp の mirror -R はディレクトリを再帰的にアップロードします。
# 個別のファイルは put でアップロードします。
UPLOAD_ITEMS=(
    "edu.ontheroad.jp/index.cgi"
    "web/"
    "venv/"
)

# lftp コマンドを構築
LFTP_COMMAND="set ftp:ssl-allow no; set ftp:sync-mode on; set mirror:set-permissions no; cd $REMOTE_DIR;"

for item in "${UPLOAD_ITEMS[@]}"; do
    LOCAL_ITEM_PATH="$LOCAL_PROJECT_ROOT/$item"
    REMOTE_ITEM_PATH="$item" # REMOTE_DIR は既に cd で移動済みなので、相対パスで指定

    if [ -f "$LOCAL_ITEM_PATH" ]; then
        echo "Uploading file: $LOCAL_ITEM_PATH to $REMOTE_DIR/$REMOTE_ITEM_PATH"
        LFTP_COMMAND+="put -O $REMOTE_DIR $LOCAL_ITEM_PATH;"
    elif [ -d "$LOCAL_ITEM_PATH" ]; then
        # __pycache__ や .git はアップロードしない
        if [[ "$item" == "__pycache__/" || "$item" == ".git/" ]]; then
            echo "Skipping directory: $LOCAL_ITEM_PATH"
            continue
        fi
        echo "Mirroring directory: $LOCAL_ITEM_PATH to $REMOTE_DIR/$REMOTE_ITEM_PATH"
        # mirror -R はローカルからリモートへのミラーリング
        # --exclude-glob を使って除外したいファイルを指定することも可能
        LFTP_COMMAND+="mirror -R --ignore-time --exclude-glob '__pycache__/*' --exclude-glob '.git/*' --dereference $LOCAL_ITEM_PATH $REMOTE_ITEM_PATH;"
    else
        echo "Warning: $LOCAL_ITEM_PATH not found. Skipping."
    fi
done

# lftp を実行
lftp -u "$FTP_USER","$FTP_PASS" "$FTP_HOST" -e "$LFTP_COMMAND quit"

if [ $? -eq 0 ]; then
    echo "\nDeployment completed successfully!"
else
    echo "\nDeployment failed!"
    exit 1
fi


