#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import cgitb
cgitb.enable()

import os
import json
import secrets
from flask import (
    Flask, render_template, send_from_directory,
    redirect, url_for, request, flash, session
)
from flask_login import (
    LoginManager, UserMixin, login_user, logout_user,
    login_required, current_user
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime
from wsgiref.handlers import CGIHandler

# --- Flaskアプリケーションの初期化 ---
app = Flask(__name__, instance_relative_config=True, template_folder='templates', static_folder='static')

project_root = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))

SECRET_KEY_FILE = 'secret_key.txt'
if os.path.exists(SECRET_KEY_FILE):
    with open(SECRET_KEY_FILE, 'r') as f:
        app.config['SECRET_KEY'] = f.read().strip()
else:
    random_secret_key = secrets.token_hex(16)
    with open(SECRET_KEY_FILE, 'w') as f:
        f.write(random_secret_key)
    app.config['SECRET_KEY'] = random_secret_key

app.config['SESSION_COOKIE_SECURE'] = False
app.config['SESSION_REFRESH_EACH_REQUEST'] = True
app.config['APP_TITLE'] = '中学受験 2026年度向け 過去問分析レポート' # 変更

os.makedirs(app.instance_path, exist_ok=True)
app.config['SQLALCHEMY_DATABASE_URI'] = f"sqlite:///{os.path.join(app.instance_path, 'users.db')}"
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'

# --- 定数 ---
JSON_INPUT_FILE = os.path.join(project_root, 'note_reports.json')
PDF_DIR = os.path.join(project_root, 'pdf_reports')
MD_OUTPUT_DIR = os.path.join(project_root, 'md_reports')

SUBJECT_MAP = {
    "国語": "japanese",
    "算数": "math",
    "理科": "science",
    "社会": "social_studies"
}
SUBJECT_JA_MAP = {v: k for k, v in SUBJECT_MAP.items()}


# --- ユーザーモデル ---
class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(50), unique=True, nullable=False)
    password = db.Column(db.String(255), nullable=False)
    is_admin = db.Column(db.Boolean, default=False)

    def get_id(self):
        return str(self.id)


with app.app_context():
    db.create_all()
    if not User.query.filter_by(username="admin").first():
        admin_user = User(
            username="admin",
            password=generate_password_hash("admin"),
            is_admin=True
        )
        db.session.add(admin_user)
        db.session.commit()


@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))


# --- ヘルパー関数 ---
def load_pdf_data():
    if not os.path.exists(JSON_INPUT_FILE):
        return []

    with open(JSON_INPUT_FILE, 'r', encoding='utf-8') as f:
        reports = json.load(f)

    school_list = []
    subjects = ["japanese", "math", "science", "social_studies"]

    for report in reports:
        school_name = report.get('school_name', '不明な学校')
        school_name_abc = report.get('school_name_abc', '')

        school_info = {
            "name": school_name,
            "reports": []
        }

        for subject_en in subjects:
            pdf_path_relative = os.path.join(subject_en, f"{school_name_abc}.pdf")
            pdf_path_full = os.path.join(PDF_DIR, pdf_path_relative)

            if os.path.exists(pdf_path_full):
                subject_ja = SUBJECT_JA_MAP.get(subject_en, subject_en.capitalize())
                school_info["reports"].append({
                    "subject": subject_ja,
                    "pdf_filename": pdf_path_relative
                })

        if school_info["reports"]:
            school_list.append(school_info)

    return sorted(school_list, key=lambda x: x['name'])

def load_note_links():
    if not os.path.exists(JSON_INPUT_FILE):
        return []

    with open(JSON_INPUT_FILE, 'r', encoding='utf-8') as f:
        reports = json.load(f)

    school_list = []
    ordered_subjects = ["japanese", "math", "science", "social_studies"] 

    for report in reports:
        school_name = report.get('school_name', '不明な学校')
        school_info = {
            "name": school_name,
            "reports": [] 
        }

        for subject_en in ordered_subjects: 
            note_url = report.get('past_exam_reports', {}).get(subject_en, {}).get('note_url')
            subject_ja = SUBJECT_JA_MAP.get(subject_en, subject_en.capitalize())

            school_info["reports"].append({
                "subject": subject_ja,
                "note_url": note_url 
            })

        school_list.append(school_info)

    return sorted(school_list, key=lambda x: x['name'])


# --- ルーティング ---
@app.route('/')
def index():
    """Public-facing page with links to note.com articles."""
    schools = load_note_links()
    return render_template('note_links.html', schools=schools)

@app.route('/reports')
@login_required
def reports():
    """Protected page with links to download PDF reports."""
    schools = load_pdf_data()
    return render_template('reports.html', schools=schools)

@app.route('/history')
def history():
    """Public-facing page showing the history of published reports."""
    history_data = []
    school_name_map = {}

    if os.path.exists(JSON_INPUT_FILE):
        with open(JSON_INPUT_FILE, 'r', encoding='utf-8') as f:
            reports_json_data = json.load(f)
        for report in reports_json_data:
            school_name_map[report.get('school_name_abc')] = report.get('school_name')

    for subject_en in SUBJECT_MAP.values():
        subject_dir = os.path.join(MD_OUTPUT_DIR, subject_en)
        if os.path.exists(subject_dir):
            for filename in os.listdir(subject_dir):
                if filename.endswith('.md'):
                    file_path = os.path.join(subject_dir, filename)

                    timestamp = os.path.getmtime(file_path)
                    publish_date = datetime.fromtimestamp(timestamp).strftime('%Y年%m月%d日')

                    school_name_abc = os.path.splitext(filename)[0]

                    history_data.append({
                        "date": publish_date,
                        "school_name_abc": school_name_abc,
                        "subject": SUBJECT_JA_MAP.get(subject_en, subject_en.capitalize()),
                        "file_path": os.path.join(subject_en, filename) # downloads URL用
                    })

    history_data.sort(key=lambda x: x['date'], reverse=True)

    for item in history_data:
        item['school_name'] = school_name_map.get(item['school_name_abc'], item['school_name_abc'])

    return render_template('history.html', history_data=history_data)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if current_user.is_authenticated:
        return redirect(url_for('reports'))

    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username).first()

        if user and check_password_hash(user.password, password):
            login_user(user, remember=True)
            flash('ログインしました', 'success')
            next_page = request.args.get('next')
            return redirect(next_page or url_for('reports'))
        else:
            flash('ユーザー名またはパスワードが間違っています', 'danger')
    return render_template('login.html')


@app.route('/logout')
@login_required
def logout():
    logout_user()
    flash('ログアウトしました', 'info')
    return redirect(url_for('index'))


@app.route('/downloads/<path:filename>')
@login_required
def download_file(filename):
    # PDF_DIR は project_root からの絶対パスなので、filename も相対パスで渡す
    # filename は subject_en/school_name_abc.pdf の形式で来る
    # send_from_directory はディレクトリとファイル名を別々に受け取る
    directory = os.path.join(PDF_DIR, os.path.dirname(filename))
    file_name = os.path.basename(filename)
    return send_from_directory(directory, file_name, as_attachment=True)


# --- 管理者パネル ---
@app.route('/admin')
@login_required
def admin_panel():
    if not current_user.is_admin:
        flash("管理者権限が必要です。")
        return redirect(url_for('reports'))
    all_users = User.query.all()
    return render_template('admin.html', users=all_users)


@app.route("/add_user", methods=["POST"])
@login_required
def add_user():
    if not current_user.is_admin:
        flash("権限がありません。")
        return redirect(url_for("reports"))

    username = request.form["username"]
    password = request.form["password"]
    is_admin = bool(int(request.form.get("is_admin", 0)))

    if User.query.filter_by(username=username).first():
        flash("このユーザー名は既に存在します。")
        return redirect(url_for("admin_panel"))

    new_user = User(
        username=username,
        password=generate_password_hash(password),
        is_admin=is_admin,
    )
    db.session.add(new_user)
    db.session.commit()

    flash("ユーザーを追加しました。")
    return redirect(url_for("admin_panel"))


@app.route("/delete_user/<int:user_id>", methods=["POST"])
@login_required
def delete_user(user_id):
    if not current_user.is_admin:
        flash("権限がありません。")
        return redirect(url_for("reports"))

    user = User.query.get_or_404(user_id)
    if user.id == current_user.id:
        flash("自分自身は削除できません。")
        return redirect(url_for("admin_panel"))

    db.session.delete(user)
    db.session.commit()
    flash("ユーザーを削除しました。")
    return redirect(url_for("admin_panel"))


@app.route("/change_password/<int:user_id>", methods=["POST"])
@login_required
def change_password(user_id):
    if not current_user.is_admin:
        flash("権限がありません。")
        return redirect(url_for("reports"))

    new_password = request.form["new_password"]
    user = User.query.get_or_404(user_id)
    user.password = generate_password_hash(new_password)
    db.session.commit()
    flash("パスワードを変更しました。")
    return redirect(url_for("admin_panel"))


# --- 実行 ---
if __name__ == '__main__':
    CGIHandler().run(app)

